    if (!b.onBank) return { k: 'ann', label: 'Not on bank yet', cls: 'b-violet', open: open };
    if (open) return { k: 'diff', label: plural(open, 'difference'), cls: 'b-bad', open: open };
    return { k: 'ready', label: 'Matched · to reconcile', cls: 'b-blue', open: 0 };
