  function claimFor(pid) { for (var i = st.claims.length - 1; i >= 0; i--) if (st.claims[i].pid === pid) return st.claims[i]; return null; }

  // ── Seeded starting state: a work queue that has been used for a while ───
  function seedState() {
    var R = U.rng(0x5EED01), me = 'maja';
    function pick(a) { return a[Math.floor(R() * a.length)]; }
    var byCountry = { SI: ['maja', 'luka'], HR: ['ivana', 'karlo'], IT: ['giulia'] };
    var NOTES = {
      noscan: ['Asked the carrier for a status update by e-mail.', 'Carrier says it is at the depot, waiting for a scan.', 'Customer called asking where the parcel is.'],
      failed: ['Left a voicemail, will try again tomorrow.', 'Customer will be home on Friday; asked carrier to redeliver.', 'Address was missing the floor number; corrected with the carrier.'],
      pickup: ['Sent a reminder that the parcel is waiting.', 'Customer is on holiday, will collect next week.'],
      returned: ['Customer refused: no longer needed. Cancel and refund once back.', 'Customer did not collect. Will offer to resend.', 'Back in the warehouse, stock booked in.'],
      damlost: ['Photos requested from the carrier.', 'Claim prepared, waiting for the carrier reference.', 'Replacement sent to the customer.']
    };
    var ACT = { noscan: 'carrier', failed: 'call', pickup: 'call', returned: 'resend', damlost: 'claim' };
    G.parcels.forEach(function (p) {
      var iss = issuesOf(p);
      if (!iss.length) return;
      var since = U.daysBetween(p.last.ts, TODAY), k = iss[0].k;
      if (since < 1 || R() > 0.62) return;
      var c = getCase(p.id);
      c.assignee = pick(byCountry[p.country]);
      c.action = k === 'returned' && p.cod ? pick(['resend', 'wait', 'refund']) : ACT[k];
      if (R() < 0.7) c.notes.push({ ts: U.addDays(p.last.ts.slice(0, 10), Math.min(since, 1)) + 'T' + pad(9 + Math.floor(R() * 7)) + ':' + pad(Math.floor(R() * 60)), by: c.assignee, text: pick(NOTES[k]) });
      if (k === 'returned' && p.status === 'returned' && since > 6 && R() < 0.55) { c.resolved = true; c.resolvedBy = c.assignee; c.resolvedAt = U.addDays(p.last.ts.slice(0, 10), 2) + 'T10:15'; c.notes.push({ ts: c.resolvedAt, by: c.assignee, text: 'Done: return booked in, customer informed.' }); }
    });
    // COD: some differences already handled by finance, and most older batches reconciled
    mismatches().forEach(function (p) {
      var o = codOf(p);
      if (o.age < 20 || R() > 0.4) return;
      if (o.state === 'short' && R() < 0.5) { st.cod[p.id] = { how: 'reconciled', reason: 'Fee difference accepted', note: 'Carrier confirmed the surcharge on the invoice.', by: 'tina', ts: U.addDays(TODAY, -Math.floor(R() * 8 + 2)) + 'T11:20' }; return; }
      st.seq.claim++;
      var no = 'CLM-' + TODAY.slice(0, 4) + '-' + pad(st.seq.claim, 4), opened = U.addDays(TODAY, -Math.floor(R() * 10 + 3)) + 'T10:40';
      st.claims.push({ no: no, pid: p.id, carrier: p.carrier, type: o.state, amount: Math.abs(codDiff(o)), status: R() < 0.3 ? 'credited' : 'open', opened: opened, by: 'tina', note: o.state === 'overdue' ? 'Delivered parcel missing from all payout batches.' : o.state === 'short' ? 'Remittance shorter than the collected COD.' : 'Paid out although the parcel came back to us.', history: [] });
      st.cod[p.id] = { how: 'claim', claim: no, by: 'tina', ts: opened };
    });
    G.batches.forEach(function (b) { if (b.onBank && U.daysBetween(b.bankDate, TODAY) > 12 && !batchStatus(b).open && R() < 0.85) st.batches[b.id] = { by: 'tina', ts: U.addDays(b.bankDate, 1) + 'T09:30', note: '' }; });
    st.me = me;
    cache = {};
  }

