    var unassigned = q.filter(function (p) { var c = caseOf(p.id); return !c || !c.assignee; }).length;
    var mine = q.filter(function (p) { var c = caseOf(p.id); return c && c.assignee === st.me; }).length;
    var ruleCount = {}; q.forEach(function (p) { var k = primaryRule(p); ruleCount[k] = (ruleCount[k] || 0) + 1; });
    var seg = '<div class="seg" role="group" aria-label="Country">' + [['', 'All'], ['SI', 'SI'], ['HR', 'HR'], ['IT', 'IT']].map(function (x) { return '<button type="button" data-act="ovCountry" data-v="' + x[0] + '" aria-pressed="' + (stO.country === x[0]) + '" data-fid="ovc-' + (x[0] || 'all') + '">' + x[1] + '</button>'; }).join('') + '</div>';
