    if (p.at_pickup_point_at || p.status === 'at_pickup_point' || p.status === 'pickup_point_expired' || p.carrier === 'BOX NOW') steps.push([p.carrier === 'BOX NOW' ? 'In locker' : 'At pickup point', p.at_pickup_point_at]);
    if (bad) steps.push([lstat(p.status)[0], p.returned_to_sender_at || p.return_started_at || p.status_at]);
    else steps.push(['Delivered', p.delivered_at]);
